    'faq_note' => 'жауаптар дейін common сұрақтар.',
    'faq_q1' => '<strong>What болып табылады TropaTT?</strong><br>A free ашу-көзі self-hosted CRM, тапсырма менеджер, және жоба management platform.',
    'faq_q10' => 'Who болып табылады developer?',
    'faq_q10_answer' => '<strong>Anton Barinov</strong>, a PHP developer.',
    'faq_q2' => '<strong>Is it a CRM немесе a тапсырма менеджер?</strong><br>Both. A CRM үшін клиенттер және counterparties, a тапсырма менеджер үшін тапсырмалар, plus жоба management, chat, күнтізбе, және AI.',
    'faq_q3' => '<strong>Is it suitable үшін freelancers?</strong><br>Yes. There болып табылады жоқ ең аз команда өлшем. A single пайдаланушы gets CRM, тапсырмалар, an AI күн жоспар, және chat жоқ per-seat fees.',
    'faq_q4' => '<strong>Does it жұмыс үстінде shared hosting?</strong><br>Yes. PHP 8.1+ және MySQL болып табылады enough. browser installer configures everything.',
    'faq_q5' => '<strong>Are there шектеулер үстінде пайдаланушылар және тапсырмалар?</strong><br>No. Unlimited пайдаланушылар, тапсырмалар, жобалар, және клиенттер. тек limitation болып табылады server capacity.',
    'faq_q6' => '<strong>Where болып табылады деректер stored?</strong><br>100% үстінде сіздің server. жүйе never syncs деректер дейін cloud.',
    'faq_q7' => '<strong>What AI tools болып табылады қолжетімді?</strong><br>20+ tools: идея exploration, күн/апта жоспарлар, summaries, тексеру тізімдері, тәуекелдер, кездесу preparation.',
    'faq_q8' => '<strong>Is there an API?</strong><br>Yes, a REST API бірге an OpenAPI 3.1 spec жасалды бастап код.',
    'faq_q9' => '<strong>Can it болу customized?</strong><br>Yes. PHP код, модульдер, вебхуктар, API, жұмыс процесі rules, арнайы өрістер, рөлдер, және қолжетімділік rights.',
    'faq_title' => 'Frequently asked сұрақтар',
    'gantt_intro' => 'Gantt displays жоба тапсырмалар үстінде a уақыт шкаласы. It lets сіз жоспар deadlines, track dependencies, және monitor resource overload.',
    'gantt_item1' => 'әр тапсырма болып табылады displayed as a bar үстінде уақыт шкаласы.',
    'gantt_item2' => 'Dependencies: тапсырма B depends үстінде тапсырма A — shown үстінде Gantt as a link.',
    'gantt_item3' => 'критикалық path: sequence бойынша тапсырмалар сол determines ең аз жоба ұзақтығы.',
    'gantt_note' => 'жоба уақыт шкаласы бірге dependencies.',
    'gantt_title' => 'Gantt chart',
    'ideas_intro' => 'A модуль үшін жұмыс істейтін бірге жаңа ideas, жобалар, және proposals.',
    'ideas_lifecycle_heading' => 'идея lifecycle',
    'ideas_link' => 'Идеялар',
