    'ideas_note' => 'Full цикл: бастап a raw идея дейін a тапсырма жоспар.',
    'ideas_restart_note' => 'әрбір қадам can болу restarted. AI results болып табылады always алдын ала қарау-тек until confirmed.',
    'ideas_step1' => '<strong>Create an idea</strong> — тақырып, қысқа сипаттама, category, region, мақсат күн.',
    'ideas_step10' => '<strong>Final recommendation</strong> — қорытынды және AI verdict.',
