    'mcp_title' => 'AI Agents (MCP)',
    'mcp_note' => 'Connect Claude код, Codex, ChatGPT, және other AI agents дейін CRM.',
    'mcp_why' => '<strong>Why:</strong> MCP allows AI agents дейін оқу және басқару сіздің тапсырмалар, жобалар, клиенттер, және chats through a unified protocol — бірге same қолжетімділік рұқсаттар as web UI.',
    'mcp_intro' => 'TropaTT includes a built-ішінде MCP (модель Context Protocol) server — same protocol understood арқылы Claude код, Codex, ChatGPT, және other compatible AI agents.',
    'mcp_item1' => '<strong>620 MCP tools + 6 resources</strong> — тапсырмалар, жобалар, клиенттер, contacts, chats, күнтізбе, аналитика, білім база.',
    'mcp_item2' => '<strong>Same деректер және rules</strong> — әрбір сұрау goes through REST API және RBAC checks, just like web интерфейс.',
    'mcp_item3' => '<strong>Security</strong> — sensitive деректер (токендер, құпиясөз hashes, API кілттер) болып табылады filtered; writes require appropriate рұқсаттар.',
    'mcp_item4' => '<strong>Endpoint:</strong> POST /api/index.php?route=api/v1/mcp, authentication via Bearer токен.',
    'mcp_docs_link' => 'Full MCP documentation:',
    'usage_title' => 'Usage Examples',
    'usage_note' => 'Concrete scenarios үшін different рөлдер және industries.',
    'usage_why' => '<strong>Why:</strong> these examples show how TropaTT болып табылады used ішінде real жұмыс процестері — бастап incoming сұрау дейін аяқталған тапсырма.',
    'usage_cycle_heading' => 'Full клиент жұмыс цикл',
    'usage_step1' => '<strong>Capture</strong> — идея, клиент сұрау, problem, немесе incoming lead.',
    'usage_step2' => '<strong>Analysis</strong> — үстінде сіздің own немесе бірге AI: қолданылу аясы, тәуекелдер, feasibility, approach.',
    'usage_step3' => '<strong>Structure</strong> — into жобалар, тапсырмалар, subtasks, тексеру тізімдері, assignees, deadlines.',
    'usage_step4' => '<strong>Coordination</strong> — via chat, пікірлер, @mentions, хабарламалар.',
    'usage_step5' => '<strong>Execution</strong> — тапсырма lists, Kanban, My күн, My апта.',
    'usage_step6' => '<strong>Tracking</strong> — Gantt, dashboards, аналитика, load, тәуекел signals.',
    'usage_step7' => '<strong>Automation</strong> — жұмыс процесі rules, SLA, вебхуктар, бекіту chains.',
    'usage_examples_heading' => 'Concrete examples',
    'usage_ex1' => '<strong>Freelancer:</strong> клиент сұрау → AI analyzes → тапсырма жоспар → My күн → execution → клиент chat → done.',
    'usage_ex2' => '<strong>Agency:</strong> клиент brief → AI decomposes → жоба + milestones → Kanban → Gantt tracking → клиент есеп → аналитика.',
    'usage_ex3' => '<strong>Service company:</strong> контрагент → жоба → installation тапсырмалар → Gantt → daily жоспарлар → SLA monitoring → act signing.',
    'usage_ex4' => '<strong>B2B operations:</strong> company → contacts → тапсырмалар + бекітулер → еске салғыштар → webhook → бақылау тақтасы.',
    'tech_title' => 'Tech Stack & нөмірлер',
    'tech_note' => 'Stack, architecture, және кілт жоба metrics.',
    'tech_why' => '<strong>Why:</strong> understanding stack helps evaluate hosting requirements, customization опциялар, және жүйе scalability.',
    'tech_stack_heading' => 'Technology Stack',
    'tech_stack1' => '<strong>Backend:</strong> PHP 8.1+, арнайы microkernel. Zero сыртқы dependencies. жоқ Laravel/Symfony/Doctrine.',
    'tech_stack2' => '<strong>Database:</strong> MySQL.',
    'tech_stack3' => '<strong>Frontend:</strong> PHP-rendered MPA + Bootstrap 5 + арнайы vanilla JS ES5+ модульдер. жоқ React/Vue/Angular. жоқ bundler.',
